/* Bizadshop protected runtime loader.
   The application logic is stored as an encoded payload to make casual
   source inspection harder. This is obfuscation, not cryptographic security.
*/
(() => {
    "use strict";
    const encoded = "";
    const source = decodeURIComponent(
        Array.from(atob(encoded), c => "%" + c.charCodeAt(0).toString(16).padStart(2, "0")).join("")
    );
    const run = new Function(source);
    run();
})();
